"""Separate before/after report; never overwrite the original holdout evidence."""
import collections,html,json,hashlib,statistics
from pathlib import Path
SRC=Path('evaluation/private/unseen-regression-v2-2026-11-03');DEST=Path('site/unseen-regression')
def main():
 old=json.loads(Path('site/unseen-validation/results.json').read_text());new=json.loads((SRC/'results.json').read_text());m=json.loads((SRC/'manifest.json').read_text())
 for p,h in m['previous_run']['protected_files'].items():
  candidate=Path(p)
  if candidate.suffix=='.html' and hashlib.sha256(candidate.read_bytes()).hexdigest()!=h:candidate=candidate.with_name('original-report.html')
  assert hashlib.sha256(candidate.read_bytes()).hexdigest()==h,p
 before={r['id']:r for r in old['rows']};rows=new['rows'];assert len(rows)==15 and set(before)=={r['id'] for r in rows}
 for case in m['cases']:
  original=next(c for c in old['manifest']['cases'] if c['id']==case['id'])
  assert case['order']==original['order'] and case['expected_action']==original['expected_action']
  assert all(f['sha256']==original['files'][k]['sha256'] for k,f in case['files'].items())
 counts=collections.Counter(r['action'] for r in rows)
 summary={'actions':dict(counts),'exact_targets_met':sum(r['exact_target_met'] for r in rows),'acceptable_actions_met':sum(r['acceptable_action_met'] for r in rows),'posts_on_nonpost_targets':sum(r['action']=='post' and r['expected_action']!='post' for r in rows),'accepted_clean_targets':sum(r['action']=='post' and r['expected_action']=='post' for r in rows),'technical_failures':counts['error'],'median_seconds':round(statistics.median(r['seconds'] for r in rows),1),'scope':'Post-hoc regression on the same five photos and 15 unchanged controls; not new held-out accuracy.'}
 for c in m['cases']:
  for f in c['files'].values():f['filename']=Path(f.pop('path')).name
 interrupted=json.loads(Path('evaluation/private/unseen-regression-2026-11-03/results.json').read_text())
 ocr=json.loads(Path('evaluation/private/ocr-regression-2026-11-03/results.json').read_text())
 public={'focused_document_checks':ocr,'interrupted_attempt':{'completed_cases':6,'pre_call_code_drift_stops':9,'retained':True},'summary':summary,'manifest':m,'manifest_sha256':new['manifest_sha256'],'before_summary':old['summary'],'rows':rows}
 DEST.mkdir(exist_ok=True);(DEST/'interrupted-results.json').write_text(json.dumps(interrupted,ensure_ascii=False,indent=2));(DEST/'results.json').write_text(json.dumps(public,ensure_ascii=False,indent=2));Path('evaluation/unseen-regression-2026-11-03.json').write_text(json.dumps(public,ensure_ascii=False,indent=2))
 esc=lambda x:html.escape(str(x));labels={'post':'Kabul','block':'Ret','human':'İnsan incelemesi','error':'Teknik hata'}
 table=[];details=[]
 for r in rows:
  b=before[r['id']];e=r.get('evidence',{});d=e.get('decision',{});reason=' '.join(d.get('reasons',[])) or r.get('error_type','')
  table.append(f"<tr><td>{esc(r['id'])}</td><td>{labels[r['expected_action']]}</td><td>{labels[b['action']]}<br><small>{esc(b.get('rule',''))}</small></td><td>{labels[r['action']]}<br><small>{esc(r.get('rule',r.get('error_type','')))}</small></td><td>{r['seconds']:.1f} sn</td><td>{'✓' if r['exact_target_met'] else '✗'}</td></tr>")
  details.append(f"<details><summary>{esc(r['id'])}: {labels[r['action']]}</summary><p>{esc(reason)}</p><pre>{esc(json.dumps(r,ensure_ascii=False,indent=2))}</pre></details>")
 first=next(r for r in rows if r['id']=='scd-111-baseline');focus=[r for r in rows if r['source_image_id']==711]
 text=f'''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Düzeltme sonrası testler · Count Before You Post</title><style>body{{font:16px/1.6 system-ui;background:#f5f4ee;color:#17313e;margin:0}}main{{max-width:1150px;margin:auto;padding:32px 22px}}h1{{font-size:38px;line-height:1.15}}a{{color:#175bdb}}.notice{{padding:22px;background:#e7eef9;border-left:4px solid #175bdb}}table{{width:100%;border-collapse:collapse;background:white;font-size:14px}}td,th{{text-align:left;padding:12px;border-bottom:1px solid #d6dfdf}}.scroll{{overflow:auto}}details{{border-top:1px solid #d6dfdf;padding:16px 0}}summary{{font-weight:bold;cursor:pointer}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 monospace;max-height:400px;overflow:auto;background:#e9eef0;padding:18px}}</style><main><a href="../jury/">← Jüri demosu</a> · <a href="../unseen-validation/">İlk koşu — değiştirilmedi</a><h1>Aynı 15 girdi.<br>Düzeltme öncesi ve sonrası.</h1><p>3 Kasım 2026 · Düzeltme sonrası regresyon; yeni görülmemiş veri doğrulaması değildir.</p><div class="notice"><strong>{counts['post']} kabul · {counts['block']} ret · {counts['human']} insan incelemesi · {counts['error']} teknik hata.</strong><p>Kesin hedef eşleşmesi: 11/15 → {summary['exact_targets_met']}/15.<br>İnceleme/ret hedefinde beklenmeyen kabul: 1 → {summary['posts_on_nonpost_targets']}.<br>Temiz kabul hedefi: 1/1 → {summary['accepted_clean_targets']}/1.</p><p>Medyan süre: {summary['median_seconds']} sn. Gerçek ERP yazımı yok; maliyet ölçülmedi.</p></div><h2>711 sonucu</h2><ul>'''
 text+=''.join(f"<li>{esc(r['scenario'])}: {labels[before[r['id']]['action']]} → <strong>{labels[r['action']]}</strong> ({esc(r.get('rule',r.get('error_type','')))}).</li>" for r in focus)
 text+='''</ul><h2>OCR uyuşmazlığı ayrıca sınandı</h2><p>İlk koşunun iki hatalı metni korunarak aynı belgeler ikinci okuyucuya ve belge denetimine yeniden gönderildi. Bu yalnızca belge düzeyindeki kontrol; tam kabul koşusu değildir. İkinci okuyucu iki metni de başka karakterlerle yanlış okudu. Denetim iki durumda da ürün okumasını desteklemedi (ok=false, product=false). Bu çelişkili kanıtı yeni kural insana yönlendirir; karakterleri doğru okuma sorununun tamamen çözüldüğü iddia edilmiyor.</p><p>Bu iki kontrolün tüm ilk okumaları, ikinci okumaları ve denetimleri sonuç JSON dosyasının focused_document_checks alanında saklı.</p><h2>Kesintili ilk tekrar da korundu</h2><p>İlk düzeltme koşusunda ortak çalışma klasöründeki agent.py ve gate.py dosyaları başka bir işlemde değişti. Kod özeti kontrolü sonraki 9 girdiyi model çağrısı yapmadan durdurdu. İlk 6 girdi insan incelemesi kararıyla tamamlandı. Bu koşu silinmedi; aşağıda bütün satırları yer alıyor. Sonraki tam tekrar, sabit kod kopyasından 15 girdinin tamamını yeniden çalıştırdı.</p><p><a href="interrupted-results.json">Kesintili koşunun tüm ham kayıtları</a></p><h2>Ne değişti?</h2><p><strong>Bağımsız kadraj kontrolü:</strong> SAM’in tespit ettiği koli sınırı görüntünün %1 kenar bandına değerse otomatik kabul durur. Kamera okuyucusunun “tüm koliler görünür” demesi bu kontrolü aşamaz. Bu kural fotoğraf numarasına veya ürün adına bağlı değildir. Kenardan uzak olmak da tek başına gizli koli bulunmadığını kanıtlamaz.</p><p><strong>Belge uyuşmazlığını doğrulama:</strong> Tam kontrol akışında belge ürünü siparişle uyuşmadığında ikinci okuyucu ve denetim çağrılır. Okumalar çelişirse veya denetim desteklemezse insan incelemesi gerekir. İlk metin korunur; benzer harfleri tahmin ederek eşleştirme veya otomatik kabul yoktur. İki okuma ve denetim yanlış ürünü doğrularsa ret korunur.</p><p>Kadraj kontrolü daha önce durduruyorsa ikinci okumaya gerek kalmaz. Bu durumda canlı koşu OCR düzeltmesini bağımsız olarak sınamaz; “ürün adı artık her seferinde doğru okunuyor” iddiası yoktur. Okuma uyuşmazlığı, gerçek yanlış ürün ve okuyucu hatası yolları ayrıca çevrimdışı regresyon testlerinde sınandı. İki tarihsel OCR hatası için yukarıdaki taze belge okuma/denetim çağrıları da yapıldı.</p><h2>Karşılaştırmanın sınırları</h2><p>Aynı fotoğraflar, belgeler, sesler, siparişler ve önceden belirlenen hedefler kullanıldı; SHA-256 özetleri doğrulandı. Eski rapor ve sonuç dosyaları değiştirilmedi. Yeni koşunun tüm sonuçları ve hataları saklandı. Model çağrıları yeniden yapıldığı için çıktılar değişebilir; değişimin tamamını kod düzeltmesine atfetmek mümkün değildir. Bu tek tekrar ve yalnızca bir temiz kabul adayıdır.</p><p>Ürün-adı eşleştirme profili devam ediyor; kesin marka/model/SKU doğrulaması değildir. Gerçek fotoğraflara hazırlanmış belgeler ve sentetik sesler eşlik ediyor. Önceden belirlenen hedefler asistan görsel incelemesine dayanır, bağımsız saha doğrusu değildir. İnsan iş yükü ve maliyet tasarrufu ölçülmedi.</p><h2>15 kontrolün tamamı</h2><div class="scroll"><table><thead><tr><th>Kontrol</th><th>Önceden hedef</th><th>İlk koşu</th><th>Düzeltme sonrası</th><th>Süre</th><th>Hedef</th></tr></thead><tbody>'''+''.join(table)+'''</tbody></table></div><h2>Ham kayıtlar</h2><p><a href="results.json">Düzeltme sonrası tüm sonuçlar ve kod özetleri (JSON)</a> · <a href="../unseen-validation/results.json">İlk koşunun değişmeyen kaydı</a></p>'''+''.join(details)+'<h2>Kesintili koşunun 15 satırı</h2><div class="scroll"><table><tr><th>Kontrol</th><th>Sonuç</th><th>Süre</th></tr>'+''.join(f"<tr><td>{esc(r['id'])}</td><td>{'Çağrı öncesi kod sürümü kontrolünde durdu' if r['action']=='error' and r['seconds']==0 else labels[r['action']]}</td><td>{r['seconds']:.1f} sn</td></tr>" for r in interrupted['rows'])+'</table></div></main></html>'
 (DEST/'index.html').write_text(text.replace('<main>', '<script src="../i18n/ui.js" defer data-ui-i18n></script><main>', 1));print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
